import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

const routes: Routes = [
  { path: '', redirectTo: 'casecreation', pathMatch: 'full' },
  { path: 'casecreation/:id', loadComponent: () => import('../../components/casebuilder/casecreation/casecreation.component').then(m => m.CasecreationComponent) },
  { path: 'teamsetup/:id', loadComponent: () => import('../../components/casebuilder/teamsetup/teamsetup.component').then(m => m.TeamsetupComponent) }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class CasebuilderRoutingModule { }
